import { db } from "@/lib/db";
import { isPartnerRequest, verifySsoCode } from "@/lib/partner";

export const dynamic = "force-dynamic";

/**
 * Exchange an SSO code (from /sso/authorize) for the linked Nxeon identity.
 * Server-to-server: Kodely's backend calls this with its X-Api-Key. Returns the
 * Nxeon userId/email so Kodely can store the link (one account, one wallet).
 *
 * Body: { code: string, redirect_uri: string }
 */
export async function POST(req: Request) {
  if (!(await isPartnerRequest(req))) {
    return Response.json({ error: "unauthorized" }, { status: 401 });
  }
  let body: { code?: string; redirect_uri?: string };
  try {
    body = await req.json();
  } catch {
    return Response.json({ error: "invalid json" }, { status: 400 });
  }
  const userId = verifySsoCode(body.code, "kodely", body.redirect_uri ?? "");
  if (!userId) {
    return Response.json({ error: "invalid or expired code" }, { status: 400 });
  }
  const user = await db.user.findUnique({
    where: { id: userId },
    select: { id: true, email: true, name: true, balanceCents: true },
  });
  if (!user) return Response.json({ error: "user not found" }, { status: 404 });

  return Response.json({
    userId: user.id,
    email: user.email,
    name: user.name,
    balanceCents: user.balanceCents,
  });
}
