# Kodely — reverse proxy to the kodely-app VM (10.20.0.30). Separate from the auto-generated nxeon vhosts.
# Cloudflare terminates SSL at the edge (set the kodely zones to "Flexible" for now; origin is HTTP:80).
server {
    listen 80;
    listen [::]:80;
    server_name kodely.me www.kodely.me staging.kodely.me kodely.site *.kodely.site;

    location /.well-known/acme-challenge/ { root /var/www/certbot; }

    location / {
        proxy_pass http://10.20.0.30:80;
        proxy_http_version 1.1;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Connection $connection_upgrade;
        proxy_read_timeout 300s;
    }
}
